#! /usr/bin/perl
use Getopt::Long;
use POSIX qw(ceil floor);
#######################################################
# Author:  Andreas Olofsson, Nov 11, 2015
#######################################################
$Usage =<<EOF;
#######################################################
Usage: egen.pl  -mode <random|memcpy>
                -n    <number-of-bytes>
                -bl   <max-burst-in-bytes>
#######################################################
Description: 
* Generates random Epiphany 104 bit packet transaction
* Data is completely random
* Data sizes are completely random
* Address fields are random (but legal)
* Random burst sizes up to <max-burst-length>
* Default return address base is 810D0000
* Default destination address base is 83000000
#################################################################
Example1: Generate a random test

egen.pl -mode random -n 1024 -bl 128

Example2:

egen.pl -mode memcpy -n 1024 -dstaddr 90000000 -srcaddr 80000000

################################################################
EOF
$result = GetOptions('mode:s',
		     'dstaddr:s', 
		     'srcaddr:s',
		     'd:s',
		     'c:s',  #ctrlmode 
		     'n:s',
		     'bl:s',
		     '32:s',
    );


if ((!defined $opt_n) | (!defined $opt_mode) ) {
    printf $Usage;
    exit;
}
$n=$opt_n;
$mode=$opt_mode;
#####################################################################
# OPTIONAL OPTIONS
#####################################################################

#MAX BURST
if(defined $opt_bl){
    $burst_max = $opt_bl;
}
else{
    $burst_max = 4;
}

#LIMIT TO 32 BITS
if(defined $opt_32){
    $ctrl_max = 5;
}
else{
    $ctrl_max = 7;
}
if(defined $did){
    $addrid = $opt_did;
}
else{
    $addrid  =hex("0x83000000"); #NOTE: should not be equal to RX ID
}
if(defined $sid){
    $returnid=$sid;
}
else{
    $returnid=hex("0x810D0000");
}
if(defined $opt_c){
    $cltrmode=$opt_c;
}
else{
    $ctrlmode = 5;	
}

$count =0;
$bytes=0;
#Writes
$dstaddr    = hex($opt_dstaddr);
$returnaddr = $returnid+ (hex($opt_srcaddr) & 0x000FFFFF);
while($bytes<$n){
    if($mode eq "random"){
	$ctrlmode = (int(rand(hex($ctrl_max))) + 1)  | 0x1;  #only writes
	$burst    = (int(rand($opt_bl)) + 1);         #variable bursts
    }
    else{

	$burst = $n;
    }
    #BYTES
    if($ctrlmode<2){
	$addrmask = hex("0x0000ffff");
	$maskhi   = hex("0x00000000");
	$masklo   = hex("0x000000FF");
	$incr     = 1;
    }
    #HALF-WORD
    elsif($ctrlmode<4){
	$addrmask = hex("0x0000fffe");
	$maskhi   = hex("0x00000000");
	$masklo   = hex("0x0000FFFF");
	$incr     = 2;
    }
    #WORD
    elsif($ctrlmode<6){
	$addrmask = hex("0x0000fffc");
	$maskhi   = hex("0x00000000");
	$masklo   = hex("0xFFFFFFFF");
	$incr     = 4;
    }
    #DOUBLE
    else{
	$addrmask = hex("0x0000fff8");
	$maskhi   = hex("0xFFFFFFFF");
	$masklo   = hex("0xFFFFFFFF");
	$incr     = 8;
    }
    $burst=floor($burst/$incr);

    #randomize destination address
    if($mode eq "random"){
	$dstaddr    = $addrid + ((int(rand(hex("0xFFFFFFFF"))) + 0) & $addrmask); #filter "D/F group" and illegal alings
	$returnaddr = $returnid+((int(rand(hex("0xFFFFFFFF")))) & $addrmask);
    }
    #create a burst of transactions
    for ($j=0;$j<$burst;$j++){ 
	$datalo     = (int(rand(hex("0xFFFFFFFF"))) + 0) & 0xFFFFFFFF;	
	$datahi     = (int(rand(hex("0xFFFFFFFF"))) + 0) & 0xFFFFFFFF;		    

	#make sure address wasn't used already
	$inuse=0;
	for($k=0;$k<$incr;$k++){	    
	    $addr=$dstaddr+$k;
	    #check if in use
	    if(exists ($usedaddr{$addr})){
		$inuse=1;
	    }
	    #set as used	       
	    $usedaddr{$addr}=1;
	}	   
	if($inuse == 0){
	    $transaction[$count]{dstaddr}   =$dstaddr;
	    $transaction[$count]{srcaddr}   =$datahi;
	    $transaction[$count]{data}      =$datalo;
	    $transaction[$count]{reslo}     =$datalo & $masklo;
	    $transaction[$count]{reshi}     =$datahi & $maskhi; 
	    $transaction[$count]{ctrlmode}  =$ctrlmode;
	    $transaction[$count]{returnaddr}=$returnaddr;
	    $transaction[$count]{burst}     =$burst;		
	    printf("%08x_%08x_%08x_%02x_0000//WRITE (i=%d, j=%d, bytes=%d)\n",
		   $datahi,$datalo,$dstaddr,$ctrlmode, $count, $j, $bytes);
	    $bytes      = $bytes+$incr;
	    $count      = $count+1;
	    $dstaddr    = $dstaddr+$incr;
	    $returnaddr = $returnaddr+$incr;
	}	    	   	   
	else{
	    #printf("ADDR %08x in USE (CTRLMODE=%04x)\n",$dstaddr,$ctrlmode);
	}
	#print "b=$bytes incr=$incr transaction-burst=$burst ctrl=$ctrlmode count=$count use=$inuse n=$n\n";
    }
}
#Reads/Expected results
for ($i=0;$i<($#transaction+1);$i++){
    #Pushing read transactions
    printf("%08x_%08x_%08x_%02x_0000//READ\n",
	   $transaction[$i]{returnaddr},       #address to return to
	   hex("0xDEADBEEF"), 
	   $transaction[$i]{dstaddr},           
	   $transaction[$i]{ctrlmode}&hex(0x6) #turn write into read
	);	
    #Expected results
    printf("%08x_%08x_%08x_%02x\n",
	   $transaction[$i]{reshi},
	   $transaction[$i]{reslo},
	   $transaction[$i]{returnaddr},
	   $transaction[$i]{ctrlmode}
	);	
}

/*******************************************************************************
 * Function:  Memory Mapped Transaction --> Packet Converter
 * Author:    Andreas Olofsson
 * License:   MIT (see LICENSE file in OH! repository)
 *
 * Documentation:
 *
 * The following table shows the field mapping for different AW's:
 *
 *  | Packet  | AW16    | AW32     | AW64   | AW128   |
 *  |---------|---------|----------|--------|---------|
 *  | 15:0    | DA,CMD  | CMD      | CMD    | CMD     |
 *  | 47:16   | D/SA,DA | DA0      | DA0    | DA0     |
 *  | 79:48   | ****    | D0/SA0   | D0/SA0 | D0/SA0  |
 *  | 111:80  | ****    | D1/0     | D1/SA1 | D1/SA1  |
 *  |---------|---------|----------|--------|---------|
 *  | 143:112 | ****    | ***      | DA1    | DA1     |
 *  |---------|---------|----------|--------|---------|
 *  | 167:144 | ****    | ***      | D2     | D2/SA2  |
 *  | 207:176 | ***     | ****     | D3     | D3/SA3  |
 *  | 239:208 | ****    | ****     | ****   | DA2     |
 *  | 271:240 | ****    | ****     | ****   | DA3     |
 *  |---------|---------|----------|--------|---------|
 *  | 303:272 | ****    | ****     | ***    | D4      |
 *  | 335:304 | ****    | ****     | ****   | D5      |
 *  | 367:336 | ****    | ****     | ****   | D6      |
 *  | 399:368 | ****    | ****     | ****   | D7      |
 *
 * The following list shows the widths supported for each AW
 *
 *  |Packet         | AW16  | AW32   | AW64   | AW128  |
 *  |---------------|-------|--------|--------|--------|
 *  |minimum        | 40    | 72+8   | 136+8  | 264+8  |
 *  |double/atomics | --    | 104+8  | 200+8  | 392+8  |
 *
 * The command field has the following options:
 *
 *
 *  | Command[15:0]   | 15:11     | 10:8      | 7:4      | 3:0  |
 *  |-----------------|-----------|-----------|----------|------|
 *  | WRITE-START     | USER[7:3] | SIZE[2:0] | LEN[3:0] | 0000 |
 *  | WRITE-STOP      | USER[7:3] | SIZE[2:0] | LEN[3:0] | 0001 |
 *  | WRITE-MULTICAST | USER[7:3] | SIZE[2:0] | LEN[3:0] | 0010 |
 *  | TBD             | USER[7:3] | SIZE[2:0] | LEN[3:0] | 0011 |
 *  | TBD             | USER[7:3] | SIZE[2:0] | LEN[3:0] | 0100 |
 *  | TBD             | USER[7:3] | SIZE[2:0] | LEN[3:0] | 0101 |
 *  | TBD             | USER[7:3] | SIZE[2:0] | LEN[3:0] | 0110 |
 *  | TBD             | USER[7:3] | SIZE[2:0] | LEN[3:0] | 0111 |
 *  |-----------------|-----------|-----------|----------|------|
 *  | READ            | USER[7:3] | SIZE[2:0] | LEN[3:0] | 1000 |
 *  | TBD             | USER[7:3] | SIZE[2:0] | LEN[3:0] | 1010 |
 *  | TBD             | USER[7:3] | SIZE[2:0] | LEN[3:0] | 1010 |
 *  | CAS             | USER[7:3] | SIZE[2:0] | LEN[3:0] | 1011 |
 *  | ATOMIC-ADD      | USER[7:3] | SIZE[2:0] | LEN[3:0] | 1100 |
 *  | ATOMIC-AND      | USER[7:3] | SIZE[2:0] | LEN[3:0] | 1101 |
 *  | ATOMIC-OR       | USER[7:3] | SIZE[2:0] | LEN[3:0] | 1110 |
 *  | ATOMIC-XOR      | USER[7:3] | SIZE[2:0] | LEN[3:0] | 1111 |
 *
 * SIZE DECODE:
 * 000=8b
 * 001=16b
 * 010=32b
 * 011=64b
 * 100=128b
 * 101=256b
 * 110=512b
 * 111=1024b
 *
 * LENGTH DECODE:
 * 0000=1 beat (single transaction)
 * 0001=2 beat
 * ...
 * 1111=16 beats
 *
 * AW32/AW64/AW128 formats are compatible
 * AW16 format is a standalone format not compatible with any other
 * All transactions are LSB aligned
 * No return address for AW16 (point to point)
 *
 ******************************************************************************/
module emesh_pack
  #(parameter AW = 64,
    parameter PW = 144)
   (
    //Command Inputs
    input [3:0]      opcode_in,
    input [3:0]      length_in,//burst length(1-16)
    input [2:0]      size_in,//size of each transfer
    input [7:3]      user_in, //user control field
    //Address/Data
    input [AW-1:0]   dstaddr_in, //destination address
    input [AW-1:0]   srcaddr_in, //source address (for reads)
    input [2*AW-1:0] data_in, //data
    //Output packet
    output [PW-1:0]  packet_out
    );

   //############################################
   // Command Field
   //############################################
   wire [15:0] 	     cmd_out;

   assign cmd_out[3:0]   = opcode_in[3:0];
   assign cmd_out[7:4]   = length_in[3:0];
   assign cmd_out[10:8]  = size_in[2:0];
   assign cmd_out[15:11] = user_in[7:3];

   //Decode (only write indicator needed)
   emesh_decode enoc_decode (//Inputs
			    .cmd_in		(cmd_out[15:0]),
			    // Outputs
			    .cmd_write		(cmd_write),
			    .cmd_write_stop	(),
			    .cmd_read		(),
			    .cmd_atomic_add	(),
			    .cmd_atomic_and	(),
			    .cmd_atomic_or	(),
			    .cmd_atomic_xor	(),
			    .cmd_cas		(),
			    .cmd_opcode		(),
			    .cmd_length		(),
			    .cmd_size		(),
			    .cmd_user		());

   generate
      //############################
      // 16-Bit ("lite/apb like")
      //############################
      if(AW==16) begin : aw16
	 if(PW==40) begin : p40
	    assign packet_out[7:0]   = cmd_out[7:0];
	    assign packet_out[23:8]  = dstaddr_in[15:0];
	    assign packet_out[39:24] = cmd_write ? data_in[15:0]:
				                   srcaddr_in[15:0];
	 end
	 else begin: perror
	    initial
	      $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
	 end
      end // block: aw16
      //######################
      // 32-Bit
      //######################
      if(AW==32) begin : aw32
	 if(PW==80) begin: p80
	    assign packet_out[15:0]   = cmd_out[15:0];
	    assign packet_out[47:16]  = dstaddr_in[31:0];
	    assign packet_out[79:48]  = cmd_write ? data_in[31:0] :
					            srcaddr_in[31:0];
	 end
	 else if(PW==112) begin: p112
	    assign packet_out[15:0]    = cmd_out[15:0];
